draw:
// Ladder of length L, base dragged out at constant speed u.
var L = p.L;
var u = p.u;

// base position, looping: x goes from 0.4 up to just under L
var xStart = 0.4;
var span = (L - 0.25) - xStart;
var period = span / u;
var x = xStart + u * (t % period);
var y = Math.sqrt(Math.max(L * L - x * x, 1e-6));
var vy = -x * u / y;                  // dy/dt
var ay = -(u * u) * (L * L) / (y * y * y); // d2y/dt2

var padL = 60, padB = 34, padT = 18, padR = 110;
var sx = (W - padL - padR) / (L * 1.1);
var sy = (H - padT - padB) / (L * 1.1);
var s = Math.min(sx, sy);
var X = function (q) { return padL + q * s; };
var Y = function (q) { return H - padB - q * s; };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// ground and wall
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(padL - 12, Y(0)); ctx.lineTo(W - padR + 10, Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(L * 1.05)); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("wall", X(0) - 34, Y(L * 0.9));
ctx.fillText("floor", W - padR - 18, Y(0) + 18);

// ladder
ctx.strokeStyle = C.accent;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(X(x), Y(0)); ctx.lineTo(X(0), Y(y)); ctx.stroke();
ctx.lineWidth = 1;

// end dots
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(x), Y(0), 4.5, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(X(0), Y(y), 4.5, 0, Math.PI * 2); ctx.fill();

// leg labels
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(0), Y(-0.12)); ctx.lineTo(X(x), Y(-0.12)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("x = " + x.toFixed(2) + " m", X(x / 2) - 26, Y(0) + 26);
ctx.fillText("y = " + y.toFixed(2) + " m", X(0) + 8, Y(y / 2));
ctx.fillStyle = C.figure;
ctx.fillText("L = " + L.toFixed(1) + " m", X(x / 2) - 6, Y(y / 2) - 6);

// velocity arrows
var arrow = function (x0, y0, dx, dy, label) {
  ctx.strokeStyle = C.figure;
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0 + dx, y0 + dy); ctx.stroke();
  var ang = Math.atan2(dy, dx);
  ctx.beginPath();
  ctx.moveTo(x0 + dx, y0 + dy);
  ctx.lineTo(x0 + dx - 7 * Math.cos(ang - 0.4), y0 + dy - 7 * Math.sin(ang - 0.4));
  ctx.lineTo(x0 + dx - 7 * Math.cos(ang + 0.4), y0 + dy - 7 * Math.sin(ang + 0.4));
  ctx.closePath();
  ctx.fillStyle = C.figure;
  ctx.fill();
  ctx.lineWidth = 1;
  ctx.fillStyle = C.figure;
  ctx.fillText(label, x0 + dx + 6, y0 + dy + 4);
};
arrow(X(x), Y(0), 30 * u, 0, "u");
arrow(X(0), Y(y), 0, Math.min(70, 22 * Math.abs(vy)), "dy/dt");

// speed bar for the top
var bx = W - padR + 26;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(bx, Y(0)); ctx.lineTo(bx, Y(L)); ctx.stroke();
var frac = Math.min(1, Math.abs(vy) / (4 * u));
ctx.strokeStyle = C.accent;
ctx.lineWidth = 5;
ctx.beginPath(); ctx.moveTo(bx, Y(0)); ctx.lineTo(bx, Y(L * frac)); ctx.stroke();
ctx.lineWidth = 1;
ctx.fillStyle = C.faint;
ctx.fillText("top speed", bx - 18, Y(L) - 6);

out.note = "x = " + x.toFixed(2) + " m, y = " + y.toFixed(2) + " m  |  dy/dt = " + vy.toFixed(3) + " m/s  |  top acceleration = " + ay.toFixed(3) + " m/s^2";
